<div class="two-col"><section class="card"><h2><?= e(t('This week’s review')) ?></h2><form class="stack" method="post" action="/review"><?= csrf_field() ?><label><?= e(t('What went well?')) ?><textarea name="wins" rows="3" maxlength="5000"><?= e($current['wins'] ?? '') ?></textarea></label><label><?= e(t('What didn’t work?')) ?><textarea name="fails" rows="3" maxlength="5000"><?= e($current['fails'] ?? '') ?></textarea></label><label><?= e(t('How would you score the week? (1–10)')) ?><input type="number" name="score" min="1" max="10" value="<?= e($current['score'] ?? '') ?>" required></label><label><?= e(t('Focus for next week')) ?><textarea name="focus" rows="2" maxlength="1000"><?= e($current['focus'] ?? '') ?></textarea></label><button><?= e(t('Save review')) ?></button></form><p class="footnote"><?= e(t('One review per ISO week. Saving again updates this week’s entry.')) ?></p></section><section class="card"><h2><?= e(t('Your score over time')) ?></h2><?php $trend=array_reverse($history); ?><?= chart('line',array_column($trend,'week'),[['label'=>t('Weekly score'),'data'=>array_column($trend,'score'),'borderColor'=>'#0071e3','tension'=>.3]],['scales'=>['y'=>['min'=>0,'max'=>10]]]) ?></section></div>
